    private sealed class CoverView : PictureBox
    {
        public bool FitEntireImage { get; init; }
        public bool UniformFrame { get; init; }
        public CoverView() { DoubleBuffered = true; BackColor = Panel; SizeMode = PictureBoxSizeMode.Normal; }
        protected override void OnPaint(PaintEventArgs e)
        {
            e.Graphics.Clear(BackColor); if (Image is null) return; e.Graphics.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic; e.Graphics.PixelOffsetMode = System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
