        }
        private static Rectangle ContentBounds(Image image)
        {
            if (image is not Bitmap bitmap || bitmap.Width < 20 || bitmap.Height < 20) return new Rectangle(0, 0, image.Width, image.Height); var left = 0; var top = 0; var right = bitmap.Width - 1; var bottom = bitmap.Height - 1; var maxX = bitmap.Width / 4; var maxY = bitmap.Height / 4;
            while (top < maxY && IsDarkRow(bitmap, top)) top++; while (bottom > bitmap.Height - 1 - maxY && IsDarkRow(bitmap, bottom)) bottom--; while (left < maxX && IsDarkColumn(bitmap, left, top, bottom)) left++; while (right > bitmap.Width - 1 - maxX && IsDarkColumn(bitmap, right, top, bottom)) right--;
            return right - left > 10 && bottom - top > 10 ? Rectangle.FromLTRB(left, top, right + 1, bottom + 1) : new Rectangle(0, 0, bitmap.Width, bitmap.Height);
        }
        private static bool IsDarkRow(Bitmap bitmap, int y) { var dark = 0; var samples = 0; for (var x = 0; x < bitmap.Width; x += 2) { var color = bitmap.GetPixel(x, y); if (color.A < 20 || Math.Max(color.R, Math.Max(color.G, color.B)) <= 12) dark++; samples++; } return dark >= samples * .96; }
        private static bool IsDarkColumn(Bitmap bitmap, int x, int top, int bottom) { var dark = 0; var samples = 0; for (var y = top; y <= bottom; y += 2) { var color = bitmap.GetPixel(x, y); if (color.A < 20 || Math.Max(color.R, Math.Max(color.G, color.B)) <= 12) dark++; samples++; } return dark >= samples * .96; }
    }

