    private static string WrapPath(string path) { if (path.Length <= 34) return path; var lines = new List<string>(); var remaining = path; while (remaining.Length > 34) { var cut = remaining.LastIndexOf('\\', Math.Min(33, remaining.Length - 1)); if (cut < 12) cut = 34; lines.Add(remaining[..cut].TrimEnd('\\')); remaining = remaining[(cut + 1)..]; } lines.Add(remaining); return string.Join(Environment.NewLine, lines); }
