    private static void OpenSteamPage(Translation item) { if (!string.IsNullOrWhiteSpace(item.SteamAppId)) OpenUrl($"https://store.steampowered.com/app/{item.SteamAppId}/"); }
    private static bool IsValidGameFolder(Translation item, string? path)
    {
        if (string.IsNullOrWhiteSpace(path) || !Directory.Exists(path)) return false;
        if (item.ExecutableHints.Count == 0) return true;
        foreach (var hint in item.ExecutableHints.Where(x => !string.IsNullOrWhiteSpace(x)))
        {
            var normalized = hint.Replace('/', Path.DirectorySeparatorChar).TrimStart(Path.DirectorySeparatorChar);
            if (File.Exists(Path.Combine(path, normalized))) return true;
            try { if (Directory.EnumerateFiles(path, Path.GetFileName(normalized), SearchOption.AllDirectories).Any()) return true; } catch (UnauthorizedAccessException) { } catch (IOException) { }
        }
        return false;
    }
    private void LocateGameManually(Translation item)
    {
