    private async Task InstallAsync(Translation item)
    {
        var updating = StateOf(item) is LibraryState.UpdateAvailable or LibraryState.VerificationRequired; var action = updating ? "Atualizar" : "Instalar"; var path = _foundPaths.GetValueOrDefault(item.Id) ?? _storage.Config.GamePaths.GetValueOrDefault(item.Id); if (string.IsNullOrWhiteSpace(path) || !Directory.Exists(path)) { MessageBox.Show(this, "O jogo não foi localizado. Execute o escaneamento.", "Jogo não encontrado", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } if (!EnsureSteamRunning()) return; if (MessageBox.Show(this, $"{action} a tradução de {item.Game}?", $"Confirmar {action.ToLowerInvariant()}", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return; if (!EnsureGameClosed(item, path)) return;
        try { SetBusy(true, updating ? "Atualizando tradução" : "Instalando tradução"); await _translations.InstallAsync(item, path, new Progress<ProgressInfo>(UpdateOperation), _closing.Token); MessageBox.Show(this, updating ? "Tradução atualizada com sucesso." : "Tradução instalada com sucesso.", "BR Patch Hub", MessageBoxButtons.OK, MessageBoxIcon.Information); } catch (Exception ex) { Log(ex.Message); MessageBox.Show(this, ex.Message, updating ? "Falha na atualização" : "Falha na instalação", MessageBoxButtons.OK, MessageBoxIcon.Error); } finally { SetBusy(false); EnsureStates(); RefreshGameList(); ShowDetails(item); }
    }
    private async Task RemoveAsync(Translation item)
    {
        if (!EnsureSteamRunning()) return; if (MessageBox.Show(this, "Desinstalar a tradução e restaurar o backup original?", "Confirmar remoção", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return; var gamePath = _storage.Installed.GetValueOrDefault(item.Id)?.GamePath ?? _storage.Config.GamePaths.GetValueOrDefault(item.Id); if (!EnsureGameClosed(item, gamePath)) return; try { SetBusy(true, "Removendo tradução"); var result = await _translations.RemoveAsync(item, new Progress<ProgressInfo>(UpdateOperation), _closing.Token); var note = result.RequiresSteamRestore ? " Alguns arquivos precisarão da verificação da Steam." : ""; MessageBox.Show(this, "Tradução removida com sucesso." + note, "BR Patch Hub", MessageBoxButtons.OK, MessageBoxIcon.Information); } catch (Exception ex) { Log(ex.Message); MessageBox.Show(this, ex.Message, "Falha na remoção", MessageBoxButtons.OK, MessageBoxIcon.Error); } finally { SetBusy(false); EnsureStates(); RefreshGameList(); ShowDetails(item); }
    }
    private async Task VerifyAsync(Translation item)
    {
        if (!_storage.Installed.TryGetValue(item.Id, out var installed)) { MessageBox.Show(this, "Esta tradução ainda não está instalada.", "Verificação", MessageBoxButtons.OK, MessageBoxIcon.Information); return; } SetBusy(true, "Verificando arquivos"); var problems = 0; IProgress<ProgressInfo> progress = new Progress<ProgressInfo>(UpdateOperation); try { await Task.Run(async () => { for (var i = 0; i < installed.Files.Count; i++) { var file = installed.Files[i]; var path = Path.Combine(installed.GamePath, file.RelativePath); if (!File.Exists(path) || !string.Equals(await FileTools.Sha256Async(path), file.InstalledHash, StringComparison.OrdinalIgnoreCase)) problems++; progress.Report(new ProgressInfo($"Verificando arquivo {i + 1} de {installed.Files.Count}", (i + 1) * 100 / Math.Max(1, installed.Files.Count))); } }); } finally { SetBusy(false); } MessageBox.Show(this, problems == 0 ? "Todos os arquivos estão corretos." : $"Foram encontrados {problems} arquivo(s) alterado(s) ou ausente(s).", "Verificação concluída", MessageBoxButtons.OK, problems == 0 ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
    }
    private void RestoreSteam(Translation item) { if (!EnsureSteamRunning()) return; if (MessageBox.Show(this, "A Steam verificará e restaurará os arquivos originais. Continuar?", "Restaurar jogo original", MessageBoxButtons.YesNo, MessageBoxIcon.Warning) != DialogResult.Yes) return; var path = _foundPaths.GetValueOrDefault(item.Id) ?? _storage.Config.GamePaths.GetValueOrDefault(item.Id); if (!EnsureGameClosed(item, path)) return; try { SteamService.Validate(item.SteamAppId); } catch (Exception ex) { MessageBox.Show(this, ex.Message, "Steam", MessageBoxButtons.OK, MessageBoxIcon.Error); } }
    private bool EnsureSteamRunning()
    {
        if (SteamService.IsRunning()) return true;
        using var dialog = new Form { Text = "Steam fechada", StartPosition = FormStartPosition.CenterParent, ClientSize = new Size(470, 190), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.FixedDialog, MaximizeBox = false, MinimizeBox = false, ShowInTaskbar = false };
        var text = new Label { Dock = DockStyle.Top, Height = 112, Padding = new Padding(22, 20, 22, 8), ForeColor = TextMain, BackColor = Panel, Font = new Font("Segoe UI", 10), Text = "A Steam precisa estar aberta antes de instalar, atualizar, remover ou restaurar uma tradução.\r\n\r\nAbra a Steam e tente novamente." };
        var buttons = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 62, FlowDirection = FlowDirection.RightToLeft, Padding = new Padding(12, 8, 18, 10), BackColor = Panel };
        var cancel = ButtonOf("Cancelar", false); cancel.Size = new Size(120, 38); cancel.Dock = DockStyle.None; cancel.DialogResult = DialogResult.Cancel;
        var open = ButtonOf("Abrir Steam", true); open.Size = new Size(130, 38); open.Dock = DockStyle.None; open.DialogResult = DialogResult.OK;
        buttons.Controls.Add(cancel); buttons.Controls.Add(open); dialog.Controls.Add(text); dialog.Controls.Add(buttons); dialog.AcceptButton = open; dialog.CancelButton = cancel;
        if (dialog.ShowDialog(this) == DialogResult.OK) { try { SteamService.Start(); } catch (Exception ex) { MessageBox.Show(this, ex.Message, "Steam", MessageBoxButtons.OK, MessageBoxIcon.Error); } }
        return false;
    }
    private bool EnsureGameClosed(Translation item, string? gamePath)
    {
        while (true)
        {
            var running = GameProcessService.FindRunning(item, gamePath);
            if (running is null) return true;
            using var dialog = new Form { Text = "Jogo em execução", StartPosition = FormStartPosition.CenterParent, ClientSize = new Size(510, 218), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.FixedDialog, MaximizeBox = false, MinimizeBox = false, ShowInTaskbar = false };
            var text = new Label { Dock = DockStyle.Fill, Padding = new Padding(22, 20, 22, 8), ForeColor = TextMain, BackColor = Panel, Font = new Font("Segoe UI", 10), Text = $"Feche o jogo para continuar.\r\n\r\nProcesso encontrado: {running}\r\n\r\nO BR Patch Hub nunca fechará o jogo à força." };
            var buttons = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 62, FlowDirection = FlowDirection.RightToLeft, Padding = new Padding(12, 8, 18, 10), BackColor = Panel };
            var cancel = ButtonOf("Cancelar", false); cancel.Size = new Size(120, 38); cancel.Dock = DockStyle.None; cancel.DialogResult = DialogResult.Cancel;
            var retry = ButtonOf("Verificar novamente", true); retry.Size = new Size(170, 38); retry.Dock = DockStyle.None; retry.DialogResult = DialogResult.Retry;
            buttons.Controls.Add(cancel); buttons.Controls.Add(retry); dialog.Controls.Add(text); dialog.Controls.Add(buttons); dialog.AcceptButton = retry; dialog.CancelButton = cancel;
            if (dialog.ShowDialog(this) != DialogResult.Retry) return false;
        }
    }
    private async Task ShowInstallQueueAsync()
    {
        if (_busy) return;
        EnsureStates();
        var choices = _catalog.Translations.Where(x => StateOf(x) is LibraryState.Available or LibraryState.UpdateAvailable).Select(x => new QueueChoice(x, _foundPaths.GetValueOrDefault(x.Id) ?? _storage.Config.GamePaths.GetValueOrDefault(x.Id) ?? "")).Where(x => Directory.Exists(x.Path)).ToList();
        if (choices.Count == 0) { MessageBox.Show(this, "Não há traduções disponíveis para instalar ou atualizar nos jogos encontrados.", "Fila de instalações", MessageBoxButtons.OK, MessageBoxIcon.Information); return; }
        using var select = new Form { Text = "Fila de instalações", StartPosition = FormStartPosition.CenterParent, ClientSize = new Size(590, 430), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.FixedDialog, MaximizeBox = false, MinimizeBox = false, ShowInTaskbar = false };
        var instruction = new Label { Dock = DockStyle.Top, Height = 58, Padding = new Padding(16, 15, 16, 4), Text = "Marque as traduções que deseja instalar ou atualizar:", ForeColor = TextMain, BackColor = Panel };
        var list = new CheckedListBox { Dock = DockStyle.Fill, BackColor = Bg, ForeColor = TextMain, BorderStyle = BorderStyle.FixedSingle, CheckOnClick = true, Font = new Font("Segoe UI", 10), IntegralHeight = false };
        foreach (var choice in choices) list.Items.Add(choice, true);
        var buttons = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 62, FlowDirection = FlowDirection.RightToLeft, Padding = new Padding(12, 8, 18, 10), BackColor = Panel };
        var cancel = ButtonOf("Cancelar", false); cancel.Size = new Size(120, 38); cancel.Dock = DockStyle.None; cancel.DialogResult = DialogResult.Cancel;
        var start = ButtonOf("Iniciar fila", true); start.Size = new Size(140, 38); start.Dock = DockStyle.None; start.DialogResult = DialogResult.OK;
        buttons.Controls.Add(cancel); buttons.Controls.Add(start); select.Controls.Add(list); select.Controls.Add(instruction); select.Controls.Add(buttons); select.AcceptButton = start; select.CancelButton = cancel;
        if (select.ShowDialog(this) != DialogResult.OK) return;
        var selected = list.CheckedItems.Cast<QueueChoice>().ToList(); if (selected.Count == 0) return; if (!EnsureSteamRunning()) return;

        using var progressForm = new Form { Text = "Fila de instalações", StartPosition = FormStartPosition.CenterParent, ClientSize = new Size(650, 390), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.FixedDialog, MaximizeBox = false, MinimizeBox = false, ShowInTaskbar = false, ControlBox = false };
        var status = new Label { Dock = DockStyle.Top, Height = 66, Padding = new Padding(18, 14, 18, 5), ForeColor = TextMain, BackColor = Panel, Text = "Preparando fila..." };
        var overall = new ProgressBar { Dock = DockStyle.Top, Height = 24, Minimum = 0, Maximum = 100, Style = ProgressBarStyle.Continuous, Margin = new Padding(18) };
        var results = new ListBox { Dock = DockStyle.Fill, BackColor = Bg, ForeColor = TextMain, BorderStyle = BorderStyle.FixedSingle, Font = new Font("Segoe UI", 9.5f) };
        var stop = false; var stopButton = ButtonOf("Cancelar pendentes", false); stopButton.Dock = DockStyle.Bottom; stopButton.Height = 48; stopButton.Click += (_, _) => { stop = true; stopButton.Enabled = false; stopButton.Text = "A fila será interrompida após o item atual"; };
        progressForm.Controls.Add(results); progressForm.Controls.Add(overall); progressForm.Controls.Add(status); progressForm.Controls.Add(stopButton); progressForm.Show(this); progressForm.Refresh();
        var ok = 0; var failed = 0; var skipped = 0; _busy = true;
        try
        {
            for (var index = 0; index < selected.Count; index++)
            {
                if (stop) { skipped += selected.Count - index; break; }
                var choice = selected[index]; status.Text = $"Item {index + 1} de {selected.Count}: {choice.Translation.Game}"; results.Items.Add($"Aguardando: {choice.Translation.Game}");
                if (!EnsureGameClosed(choice.Translation, choice.Path)) { results.Items[results.Items.Count - 1] = $"Ignorada: {choice.Translation.Game} (jogo aberto)"; skipped++; continue; }
                try
                {
                    var itemProgress = new Progress<ProgressInfo>(info => { status.Text = $"Item {index + 1} de {selected.Count}: {info.Message}"; var part = info.Percent ?? 0; overall.Value = Math.Clamp((index * 100 + part) / selected.Count, 0, 100); });
                    await _translations.InstallAsync(choice.Translation, choice.Path, itemProgress, _closing.Token); ok++; results.Items[results.Items.Count - 1] = $"Concluída: {choice.Translation.Game}";
                }
                catch (Exception ex) { failed++; Log($"Fila - {choice.Translation.Game}: {ex.Message}"); results.Items[results.Items.Count - 1] = $"Falhou: {choice.Translation.Game} — {ex.Message}"; }
                overall.Value = Math.Clamp((index + 1) * 100 / selected.Count, 0, 100); results.TopIndex = Math.Max(0, results.Items.Count - 1); Application.DoEvents();
            }
        }
        finally { _busy = false; progressForm.Close(); EnsureStates(); RefreshGameList(); if (_selected is not null) ShowDetails(_selected); }
        MessageBox.Show(this, $"Fila concluída.\r\n\r\nConcluídas: {ok}\r\nFalhas: {failed}\r\nPendentes canceladas/ignoradas: {skipped}", "Fila de instalações", MessageBoxButtons.OK, failed == 0 ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
    }
    private void ShowReportDialog(Translation item)
    {
        var state = StateText(StateOf(item)); var logLines = _log.Lines.Where(x => !string.IsNullOrWhiteSpace(x)).TakeLast(35);
        var body = $"Descrição do problema:\r\n[Conte aqui o que aconteceu]\r\n\r\n--- Diagnóstico do BR Patch Hub ---\r\nBR Patch Hub: v{AppConstants.AppVersion}\r\nWindows: {Environment.OSVersion}\r\nJogo: {item.Game}\r\nTradução: v{item.Version}\r\nEstado: {state}\r\nSteam AppID: {item.SteamAppId}\r\nData: {DateTimeOffset.Now:yyyy-MM-dd HH:mm:ss zzz}\r\n\r\nLog recente:\r\n{string.Join("\r\n", logLines)}";
        body = SanitizeReport(body, item);
        using var dialog = new Form { Text = "Prévia do relatório", StartPosition = FormStartPosition.CenterParent, ClientSize = new Size(760, 610), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.Sizable, MinimizeBox = false, ShowInTaskbar = false };
        var notice = new Label { Dock = DockStyle.Top, Height = 70, Padding = new Padding(16, 12, 16, 5), ForeColor = TextMain, BackColor = Panel, Text = "Revise o relatório antes de continuar. Caminhos pessoais foram ocultados. Nada será enviado automaticamente; o GitHub abrirá a página para sua confirmação final." };
        var preview = new TextBox { Dock = DockStyle.Fill, Multiline = true, ScrollBars = ScrollBars.Both, WordWrap = false, BackColor = Bg, ForeColor = TextMain, BorderStyle = BorderStyle.FixedSingle, Font = new Font("Consolas", 9.5f), Text = body };
        var buttons = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 62, FlowDirection = FlowDirection.RightToLeft, Padding = new Padding(12, 8, 18, 10), BackColor = Panel };
        var cancel = ButtonOf("Cancelar", false); cancel.Size = new Size(110, 38); cancel.Dock = DockStyle.None; cancel.DialogResult = DialogResult.Cancel;
        var open = ButtonOf("Abrir issue no GitHub", true); open.Size = new Size(180, 38); open.Dock = DockStyle.None; open.DialogResult = DialogResult.OK;
        var copy = ButtonOf("Copiar relatório", false); copy.Size = new Size(145, 38); copy.Dock = DockStyle.None; copy.Click += (_, _) => { Clipboard.SetText(preview.Text); MessageBox.Show(dialog, "Relatório copiado.", "BR Patch Hub", MessageBoxButtons.OK, MessageBoxIcon.Information); };
        buttons.Controls.Add(cancel); buttons.Controls.Add(open); buttons.Controls.Add(copy); dialog.Controls.Add(preview); dialog.Controls.Add(notice); dialog.Controls.Add(buttons); dialog.AcceptButton = open; dialog.CancelButton = cancel;
        if (dialog.ShowDialog(this) == DialogResult.OK) { var title = Uri.EscapeDataString($"[BR Patch Hub] Problema com {item.Game}"); var reportBody = Uri.EscapeDataString(SanitizeReport(preview.Text, item)); OpenUrl($"{IssueUrl(item)}?title={title}&body={reportBody}"); }
    }
    private string SanitizeReport(string text, Translation item)
    {
        var values = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase) { ["%USERPROFILE%"] = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ["%CENTRAL_DATA%"] = _storage.Root, ["%GAME_FOLDER%"] = _storage.Installed.GetValueOrDefault(item.Id)?.GamePath ?? _foundPaths.GetValueOrDefault(item.Id) ?? _storage.Config.GamePaths.GetValueOrDefault(item.Id) };
        foreach (var pair in values.Where(x => !string.IsNullOrWhiteSpace(x.Value)).OrderByDescending(x => x.Value!.Length)) text = text.Replace(pair.Value!, pair.Key, StringComparison.OrdinalIgnoreCase);
        return text.Length > 6000 ? text[..6000] + "\r\n[log reduzido]" : text;
    }
    private void ShowSettings()
    {
        using var dialog = new Form { Text = "Configurações — BR Patch Hub", StartPosition = FormStartPosition.CenterParent, Size = new Size(470, 330), BackColor = Panel, ForeColor = TextMain, Font = Font, FormBorderStyle = FormBorderStyle.FixedDialog, MaximizeBox = false, MinimizeBox = false }; var layout = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown, Padding = new Padding(24), BackColor = Panel, WrapContents = false }; layout.Controls.Add(LabelOf("CONFIGURAÇÕES", 14, FontStyle.Bold, TextMain, 390)); foreach (var text in new[] { "Escanear a Steam automaticamente ao iniciar", "Verificar catálogo ao iniciar", "Confirmar antes de instalar ou remover", "Mostrar log técnico quando houver erro" }) layout.Controls.Add(new CheckBox { Text = text, Checked = true, AutoSize = true, ForeColor = TextMain, Margin = new Padding(0, 12, 0, 0) }); var open = ButtonOf("Abrir pasta do BR Patch Hub", false); open.Width = 390; open.Height = 42; open.Margin = new Padding(0, 18, 0, 0); open.Click += (_, _) => OpenFolder(_storage.Root); layout.Controls.Add(open); dialog.Controls.Add(layout); dialog.ShowDialog(this);
    }
    private void ToggleLog() { if (_logToggle.Tag is not TableLayoutPanel outer) return; var visible = outer.RowStyles[1].Height > 0; outer.RowStyles[1].SizeType = SizeType.Absolute; outer.RowStyles[1].Height = visible ? 0 : 160; _logToggle.Text = visible ? "Ver log" : "Ocultar log"; }
    private void UpdateSummary() { if (_summaryCatalog.IsDisposed) return; var installed = _states.Values.Count(x => x is LibraryState.Installed or LibraryState.UpdateAvailable or LibraryState.VerificationRequired); var updates = _states.Values.Count(x => x == LibraryState.UpdateAvailable); var available = _states.Values.Count(x => x == LibraryState.Available); var missing = _states.Values.Count(x => x == LibraryState.NotFound); _summaryCatalog.Text = _catalog.Translations.Count.ToString(); _summaryInstalled.Text = installed.ToString(); _summaryUpdates.Text = updates.ToString(); _summaryAvailable.Text = available.ToString(); _summaryMissing.Text = missing.ToString(); _legendInstalled.Text = installed.ToString(); _legendUpdates.Text = updates.ToString(); _legendAvailable.Text = available.ToString(); _legendMissing.Text = missing.ToString(); }
    private LibraryState StateOf(Translation item) => _states.GetValueOrDefault(item.Id, LibraryState.NotFound);
    private static bool FilterMatches(LibraryState s, string f) => f switch { "Instalados" => s is LibraryState.Installed or LibraryState.UpdateAvailable or LibraryState.VerificationRequired, "Disponíveis" => s == LibraryState.Available, "Atualizações" => s == LibraryState.UpdateAvailable, "Não instalados" => s == LibraryState.NotFound, _ => true };
    private static string StateText(LibraryState s) => s switch { LibraryState.Installed => "Atualizada", LibraryState.Available => "Tradução não instalada", LibraryState.UpdateAvailable => "Atualização disponível", LibraryState.VerificationRequired => "Verificação necessária", _ => "Não instalado" };
    private static Color StateColor(LibraryState s) => s switch { LibraryState.Installed => Green, LibraryState.Available => Color.FromArgb(58, 156, 255), LibraryState.UpdateAvailable => Yellow, LibraryState.VerificationRequired => Color.FromArgb(255, 153, 51), _ => Gray };
    private static string CompatibilityText(Translation item, LibraryState state) => state switch { LibraryState.NotFound => "O jogo não foi encontrado. Se estiver instalado, localize a pasta manualmente.", LibraryState.Available => "Jogo localizado. Tradução pronta para instalar.", LibraryState.UpdateAvailable => "Uma nova versão está pronta para instalar.", LibraryState.VerificationRequired => "A versão instalada precisa ser verificada.", _ => string.IsNullOrWhiteSpace(item.SteamAppId) ? "Compatibilidade não verificada" : "Pronta para a versão Steam detectada" };
    private static string FormatBytes(long b) => b >= 1024 * 1024 ? $"{b / 1024d / 1024d:0.0} MB" : $"{b / 1024d:0.0} KB";
    private static string IssueUrl(Translation item) { if (Uri.TryCreate(item.ReleaseUrl, UriKind.Absolute, out var uri) && uri.Host.Equals("github.com", StringComparison.OrdinalIgnoreCase)) { var p = uri.AbsolutePath.Trim('/').Split('/'); if (p.Length >= 2) return $"https://github.com/{p[0]}/{p[1]}/issues/new"; } return AppConstants.OfficialRepositoryUrl + "/issues/new"; }
    private void SetBusy(bool busy, string? title = null) { _busy = busy; UseWaitCursor = busy; if (_operationPanel is not null && _detailRoot is not null) { _operationPanel.Visible = busy; _detailRoot.RowStyles[3].Height = busy ? 78 : 0; _detailRoot.PerformLayout(); } if (busy) { if (_operationTitle is not null && !string.IsNullOrWhiteSpace(title)) _operationTitle.Text = title; if (_operationDetail is not null) _operationDetail.Text = "Preparando..."; if (_operationPercent is not null) _operationPercent.Text = "0%"; if (_operationBar is not null) { _operationBar.Style = ProgressBarStyle.Marquee; _operationBar.MarqueeAnimationSpeed = 25; } } }
    private void UpdateOperation(ProgressInfo info) { if (InvokeRequired) { BeginInvoke(() => UpdateOperation(info)); return; } if (_operationDetail is not null) _operationDetail.Text = info.Message; _generalStatus.Text = info.Message; if (!info.Percent.HasValue) { if (_operationBar is not null) { _operationBar.Style = ProgressBarStyle.Marquee; _operationBar.MarqueeAnimationSpeed = 25; } if (_operationPercent is not null) _operationPercent.Text = "..."; return; } var percent = Math.Clamp(info.Percent.Value, 0, 100); if (_operationBar is not null) { _operationBar.Style = ProgressBarStyle.Continuous; _operationBar.Value = percent; } if (_operationPercent is not null) _operationPercent.Text = $"{percent}%"; }
    private void Log(string message) { if (InvokeRequired) { BeginInvoke(() => Log(message)); return; } _log.AppendText($"[{DateTime.Now:HH:mm:ss}] {message}\r\n"); _log.ScrollToCaret(); }
    private static void OpenUrl(string? url) { if (!string.IsNullOrWhiteSpace(url)) Process.Start(new ProcessStartInfo(url) { UseShellExecute = true }); }
    private static void OpenFolder(string? path) { if (!string.IsNullOrWhiteSpace(path) && Directory.Exists(path)) Process.Start(new ProcessStartInfo("explorer.exe", $"\"{path}\"") { UseShellExecute = true }); }
    private static Panel Card() { var p = new Panel { Dock = DockStyle.Fill, BackColor = Panel }; p.Paint += (_, e) => { using var pen = new Pen(Border); e.Graphics.DrawRectangle(pen, 0, 0, Math.Max(0, p.ClientSize.Width - 2), Math.Max(0, p.ClientSize.Height - 2)); }; return p; }
    private static Label LabelOf(string text, float size, FontStyle style, Color color, int width = 0) => new() { Text = text, Dock = width == 0 ? DockStyle.Fill : DockStyle.None, Width = width, Height = 26, ForeColor = color, BackColor = Color.Transparent, Font = new Font("Segoe UI", size, style), TextAlign = ContentAlignment.MiddleLeft, AutoEllipsis = true };
    private static Button ButtonOf(string text, bool primary) { var b = new Button { Text = text, Dock = DockStyle.Fill, Margin = new Padding(4), FlatStyle = FlatStyle.Flat, BackColor = primary ? Blue : Panel2, ForeColor = TextMain, Font = new Font("Segoe UI", 10), Cursor = Cursors.Hand, UseVisualStyleBackColor = false, TextAlign = ContentAlignment.MiddleCenter }; b.FlatAppearance.BorderSize = 1; b.FlatAppearance.BorderColor = primary ? Blue : Border; return b; }
    private static void StyleInput(Control input) { var inputColor = Color.FromArgb(30, 67, 105); input.BackColor = inputColor; input.ForeColor = TextMain; input.Font = new Font("Segoe UI", 10); if (input is TextBox textBox) { textBox.BorderStyle = BorderStyle.FixedSingle; textBox.Padding = new Padding(8, 3, 8, 3); } if (input is ComboBox comboBox) { comboBox.FlatStyle = FlatStyle.Flat; comboBox.DrawMode = DrawMode.OwnerDrawFixed; comboBox.DrawItem += (_, e) => { if (e.Index < 0) return; using var background = new SolidBrush(inputColor); e.Graphics.FillRectangle(background, e.Bounds); using var brush = new SolidBrush(TextMain); e.Graphics.DrawString(comboBox.Items[e.Index]?.ToString() ?? "", comboBox.Font, brush, e.Bounds.Left + 6, e.Bounds.Top + 2); }; } }
    private static LinkLabel LinkOf(string text, string url) { var l = new LinkLabel { Text = text, AutoSize = true, LinkColor = Color.FromArgb(58, 156, 255), ActiveLinkColor = Color.White, BackColor = Panel, Margin = new Padding(0, 9, 28, 0) }; l.LinkClicked += (_, _) => OpenUrl(url); return l; }
    private static void AddInfo(TableLayoutPanel table, int row, string name, string value) { table.RowStyles.Add(new RowStyle(SizeType.Percent, 16)); table.Controls.Add(LabelOf(name, 9, FontStyle.Regular, TextMuted), 0, row); var label = LabelOf(value, 9, FontStyle.Regular, value.Contains("OK") ? Green : TextMain); label.TextAlign = ContentAlignment.MiddleRight; table.Controls.Add(label, 1, row); }
}
